import pyomo.environ as pyo

DATA = {
    "worker_types": ["full", "part"],
    "hours_per_shift": {"full": 8, "part": 4},
    "pay_per_shift": {"full": 300, "part": 100},
    "required_hours": 500,
    "budget": 15000,
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # Set of worker types
    model.WORKER_TYPES = pyo.Set(initialize=d["worker_types"])

    # Decision variable: number of workers of each type scheduled
    model.workers = pyo.Var(
        model.WORKER_TYPES,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: minimize total number of workers
    def obj_rule(m):
        return sum(m.workers[w] for w in m.WORKER_TYPES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: meet required labor hours
    def labor_hours_rule(m):
        return sum(
            d["hours_per_shift"][w] * m.workers[w] for w in m.WORKER_TYPES
        ) >= d["required_hours"]

    model.labor_hours = pyo.Constraint(rule=labor_hours_rule)

    # Constraint: stay within budget
    def budget_rule(m):
        return sum(
            d["pay_per_shift"][w] * m.workers[w] for w in m.WORKER_TYPES
        ) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    return model


